-- 01-ticket.sql
-- 本地 prod-split 真实演示 seed，仅供联调，不属于生产迁移。
-- target database: omni_ticket_split


BEGIN;

-- 清理本 seed 保留 ID 段，避免重复执行产生脏数据。
DELETE FROM activity_review_report
WHERE activity_id BETWEEN 900001 AND 900120
   OR id BETWEEN 909201 AND 909260;
DELETE FROM activity_review
WHERE activity_id BETWEEN 900001 AND 900120
   OR id BETWEEN 909001 AND 909120;
DELETE FROM activity_question
WHERE activity_id BETWEEN 900001 AND 900120
   OR id BETWEEN 909101 AND 909180;
DELETE FROM performance_subscription
WHERE activity_id BETWEEN 900001 AND 900120
   OR artist_id BETWEEN 901001 AND 901120
   OR target_id BETWEEN 900001 AND 901120;
DELETE FROM activity_risk_resolution WHERE activity_id BETWEEN 900001 AND 900120;
DELETE FROM station_config_version WHERE activity_id BETWEEN 900001 AND 900120;
DELETE FROM session_seat WHERE session_id BETWEEN 910001 AND 910120;
DELETE FROM session_seat_layout_section WHERE session_layout_id BETWEEN 910001 AND 910120;
DELETE FROM session_seat_layout WHERE session_id BETWEEN 910001 AND 910120;
DELETE FROM ticket_type_area WHERE ticket_type_id BETWEEN 920001 AND 920360;
DELETE FROM ticket_type WHERE id BETWEEN 920001 AND 920360;
DELETE FROM session WHERE id BETWEEN 910001 AND 910120;
DELETE FROM activity_artist WHERE activity_id BETWEEN 900001 AND 900120;
DELETE FROM station WHERE activity_id BETWEEN 900001 AND 900120 OR id BETWEEN 905001 AND 905012;
DELETE FROM tour WHERE id BETWEEN 904001 AND 904003;
DELETE FROM activity WHERE id BETWEEN 900001 AND 900120;
DELETE FROM venue_application WHERE id BETWEEN 906001 AND 906006;
DELETE FROM venue_seat WHERE venue_id BETWEEN 930001 AND 930012;
DELETE FROM venue_area WHERE venue_id BETWEEN 930001 AND 930012;
DELETE FROM venue WHERE id BETWEEN 930001 AND 930012;

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, sort = EXCLUDED.sort, status = EXCLUDED.status;

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, avatar = EXCLUDED.avatar, status = EXCLUDED.status, external_links = EXCLUDED.external_links, source_note = EXCLUDED.source_note, risk_status = EXCLUDED.risk_status, review_status = EXCLUDED.review_status, review_note = EXCLUDED.review_note, update_time = EXCLUDED.update_time;

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, city = EXCLUDED.city, address = EXCLUDED.address, capacity = EXCLUDED.capacity, status = EXCLUDED.status;

ON CONFLICT (id) DO UPDATE SET venue_id = EXCLUDED.venue_id, name = EXCLUDED.name, row_count = EXCLUDED.row_count, seats_per_row = EXCLUDED.seats_per_row, color = EXCLUDED.color, sort = EXCLUDED.sort, status = EXCLUDED.status;

SELECT va.venue_id, va.id, r.row_no, s.seat_no, '第' || r.row_no || '排' || s.seat_no || '座', va.sort * 260 + s.seat_no * 18, r.row_no * 24, 1
FROM venue_area va
CROSS JOIN LATERAL generate_series(va.row_start, va.row_start + va.row_count - 1) AS r(row_no)
CROSS JOIN LATERAL generate_series(va.seat_start, va.seat_start + va.seats_per_row - 1) AS s(seat_no)
WHERE va.venue_id BETWEEN 930001 AND 930012
ORDER BY va.id, r.row_no, s.seat_no;

ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, review_note = EXCLUDED.review_note, review_time = EXCLUDED.review_time, update_time = EXCLUDED.update_time;

-- seed-real-demo:activity-start
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, poster = EXCLUDED.poster, publish_status = EXCLUDED.publish_status, seat_map_visibility = EXCLUDED.seat_map_visibility, real_name_required = EXCLUDED.real_name_required, risk_suspended_reason = EXCLUDED.risk_suspended_reason, risk_suspended_at = EXCLUDED.risk_suspended_at, update_time = EXCLUDED.update_time;
UPDATE activity
SET create_time = CURRENT_TIMESTAMP + ((id - 900001) * INTERVAL '1 second'),
    update_time = CURRENT_TIMESTAMP
WHERE id BETWEEN 900001 AND 900120;
-- seed-real-demo:activity-end


ON CONFLICT (id) DO UPDATE SET activity_id = EXCLUDED.activity_id, venue_id = EXCLUDED.venue_id, start_time = EXCLUDED.start_time, end_time = EXCLUDED.end_time, status = EXCLUDED.status;

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, total_stock = EXCLUDED.total_stock, remain_stock = EXCLUDED.remain_stock, status = EXCLUDED.status;

ON CONFLICT (id) DO UPDATE SET ticket_type_id = EXCLUDED.ticket_type_id, session_id = EXCLUDED.session_id, area_id = EXCLUDED.area_id;

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, status = EXCLUDED.status, update_time = EXCLUDED.update_time;

ON CONFLICT (id) DO UPDATE SET ticket_type_id = EXCLUDED.ticket_type_id, name = EXCLUDED.name, seat_count = EXCLUDED.seat_count, status = EXCLUDED.status, update_time = EXCLUDED.update_time;

SELECT s.id, s.venue_id, va.id, vs.id, ssls.id, 'real-demo-' || tta.ticket_type_id, vs.row_no, vs.seat_no, vs.row_no, vs.seat_no, vs.seat_label, 1, tta.ticket_type_id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM session s
JOIN venue_seat vs ON vs.venue_id = s.venue_id
JOIN venue_area va ON va.id = vs.area_id
JOIN ticket_type_area tta ON tta.session_id = s.id AND tta.area_id = va.id
JOIN session_seat_layout ssl ON ssl.session_id = s.id
JOIN session_seat_layout_section ssls ON ssls.session_layout_id = ssl.id AND ssls.ticket_type_id = tta.ticket_type_id
WHERE s.id BETWEEN 910001 AND 910120;
UPDATE session_seat ss SET status = 3, update_time = CURRENT_TIMESTAMP WHERE ss.session_id BETWEEN 910001 AND 910120 AND ss.ticket_type_id IN (SELECT id FROM ticket_type WHERE remain_stock = 0 AND session_id BETWEEN 910001 AND 910120);

ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, poster = EXCLUDED.poster, review_status = EXCLUDED.review_status, update_time = EXCLUDED.update_time;

ON CONFLICT (id) DO UPDATE SET activity_id = EXCLUDED.activity_id, city = EXCLUDED.city, station_name = EXCLUDED.station_name, publish_status = EXCLUDED.publish_status, update_time = EXCLUDED.update_time;

ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, review_note = EXCLUDED.review_note, updated_at = EXCLUDED.updated_at;

ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, review_note = EXCLUDED.review_note, update_time = EXCLUDED.update_time;

ON CONFLICT (id) DO UPDATE
SET rating = EXCLUDED.rating,
    content = EXCLUDED.content,
    images = EXCLUDED.images,
    like_count = EXCLUDED.like_count,
    status = EXCLUDED.status,
    create_time = EXCLUDED.create_time;

ON CONFLICT (id) DO UPDATE
SET content = EXCLUDED.content,
    answer = EXCLUDED.answer,
    answered_by = EXCLUDED.answered_by,
    status = EXCLUDED.status,
    create_time = EXCLUDED.create_time,
    answered_at = EXCLUDED.answered_at;

ON CONFLICT (id) DO UPDATE
SET reason = EXCLUDED.reason,
    status = EXCLUDED.status,
    handled_by = EXCLUDED.handled_by,
    handle_note = EXCLUDED.handle_note,
    create_time = EXCLUDED.create_time,
    handled_at = EXCLUDED.handled_at;

SELECT setval('artist_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM artist), 1), 1), true);
SELECT setval('venue_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM venue), 1), 1), true);
SELECT setval('activity_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM activity), 1), 1), true);
SELECT setval('session_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM session), 1), 1), true);
SELECT setval('ticket_type_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM ticket_type), 1), 1), true);
SELECT setval('activity_review_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM activity_review), 1), 1), true);
SELECT setval('activity_question_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM activity_question), 1), 1), true);
SELECT setval('activity_review_report_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM activity_review_report), 1), 1), true);
COMMIT;
